"""Exact Route 22 author-delegated ordinary encounter delta preservation normalization."""
from approved_route2_changes import prior_route2_source, restore_prior_route2_text

ORIGINAL_ROUTE22_SLOTS = "\"mons\": [\n              {\n                \"min_level\": 3,\n                \"max_level\": 3,\n                \"species\": \"SPECIES_RATTATA\"\n              },\n              {\n                \"min_level\": 3,\n                \"max_level\": 3,\n                \"species\": \"SPECIES_MANKEY\"\n              },\n              {\n                \"min_level\": 4,\n                \"max_level\": 4,\n                \"species\": \"SPECIES_RATTATA\"\n              },\n              {\n                \"min_level\": 4,\n                \"max_level\": 4,\n                \"species\": \"SPECIES_MANKEY\"\n              },\n              {\n                \"min_level\": 2,\n                \"max_level\": 2,\n                \"species\": \"SPECIES_RATTATA\"\n              },\n              {\n                \"min_level\": 2,\n                \"max_level\": 2,\n                \"species\": \"SPECIES_MANKEY\"\n              },\n              {\n                \"min_level\": 3,\n                \"max_level\": 3,\n                \"species\": \"SPECIES_SPEAROW\"\n              },\n              {\n                \"min_level\": 5,\n                \"max_level\": 5,\n                \"species\": \"SPECIES_SPEAROW\"\n              },\n              {\n                \"min_level\": 5,\n                \"max_level\": 5,\n                \"species\": \"SPECIES_RATTATA\"\n              },\n              {\n                \"min_level\": 5,\n                \"max_level\": 5,\n                \"species\": \"SPECIES_MANKEY\"\n              },\n              {\n                \"min_level\": 5,\n                \"max_level\": 5,\n                \"species\": \"SPECIES_RATTATA\"\n              },\n              {\n                \"min_level\": 5,\n                \"max_level\": 5,\n                \"species\": \"SPECIES_MANKEY\"\n              }\n            ]"
BALANCED_ROUTE22_SLOTS = "\"mons\": [\n              {\n                \"min_level\": 3,\n                \"max_level\": 3,\n                \"species\": \"SPECIES_SPEAROW\"\n              },\n              {\n                \"min_level\": 3,\n                \"max_level\": 3,\n                \"species\": \"SPECIES_NIDORAN_F\"\n              },\n              {\n                \"min_level\": 4,\n                \"max_level\": 4,\n                \"species\": \"SPECIES_SPEAROW\"\n              },\n              {\n                \"min_level\": 3,\n                \"max_level\": 3,\n                \"species\": \"SPECIES_NIDORAN_M\"\n              },\n              {\n                \"min_level\": 4,\n                \"max_level\": 4,\n                \"species\": \"SPECIES_NIDORAN_M\"\n              },\n              {\n                \"min_level\": 3,\n                \"max_level\": 3,\n                \"species\": \"SPECIES_MANKEY\"\n              },\n              {\n                \"min_level\": 4,\n                \"max_level\": 4,\n                \"species\": \"SPECIES_NIDORAN_F\"\n              },\n              {\n                \"min_level\": 5,\n                \"max_level\": 5,\n                \"species\": \"SPECIES_MANKEY\"\n              },\n              {\n                \"min_level\": 4,\n                \"max_level\": 4,\n                \"species\": \"SPECIES_TYROGUE\"\n              },\n              {\n                \"min_level\": 5,\n                \"max_level\": 5,\n                \"species\": \"SPECIES_TYROGUE\"\n              },\n              {\n                \"min_level\": 4,\n                \"max_level\": 4,\n                \"species\": \"SPECIES_TYROGUE\"\n              },\n              {\n                \"min_level\": 5,\n                \"max_level\": 5,\n                \"species\": \"SPECIES_TYROGUE\"\n              }\n            ]"


def restore_route22_text(path, source):
    if str(path) != "src/data/wild_encounters.json":
        return source
    assert source.count(BALANCED_ROUTE22_SLOTS) == 2, "Unexpected Route 22 source change"
    return source.replace(BALANCED_ROUTE22_SLOTS, ORIGINAL_ROUTE22_SLOTS)


def prior_route22_source(path):
    return restore_route22_text(path, prior_route2_source(path).decode("utf-8")).encode("utf-8")


def restore_prior_route22_text(path, source):
    return restore_route22_text(path, restore_prior_route2_text(path, source))
